import{_ as d,o as e,c as a,ag as i}from"./chunks/framework.DaCm-iTo.js";const b=JSON.parse('{"title":"EmakiAttribute","description":"","frontmatter":{},"headers":[],"relativePath":"modules/attribute/index.md","filePath":"modules/attribute/index.md","lastUpdated":null}'),r={name:"modules/attribute/index.md"};function o(l,t,c,s,n,h){return e(),a("div",null,[...t[0]||(t[0]=[i(`<h1 id="emakiattribute" tabindex="-1">EmakiAttribute <a class="header-anchor" href="#emakiattribute" aria-label="Permalink to &quot;EmakiAttribute&quot;">​</a></h1><p>EmakiAttribute 负责真实属性、资源和战斗结算。它定义 RPG 属性、伤害类型和条件，并为其他模块提供 PDC 属性 API。装备属性应写入 Attribute payload，而不是只写在 Lore 里。</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>模块版本</td><td><code>4.6.9</code></td></tr><tr><td>主命令</td><td><code>/emakiattribute</code></td></tr><tr><td>别名</td><td><code>/eattribute</code>、<code>/ea</code></td></tr><tr><td>硬依赖</td><td>EmakiCoreLib</td></tr><tr><td>软依赖</td><td>MythicMobs、PlaceholderAPI、MMOItems</td></tr><tr><td>默认权限</td><td><code>emakiattribute.use</code>、<code>emakiattribute.points</code> 默认 true；其余管理权限默认 op</td></tr></tbody></table><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>当原版属性不足以表达 RPG 战斗时，可以用 EmakiAttribute 定义自己的属性和伤害逻辑，例如：</p><ul><li>物理攻击、法术攻击、投射物攻击。</li><li>物理防御、法术防御、投射物防御。</li><li>暴击率、暴击伤害、暴击抵抗。</li><li>护甲穿透、法术穿透、真实伤害。</li><li>生命、法力、生命恢复、法力恢复。</li><li>闪避、吸血、攻速、移动速度、原版属性映射。</li></ul><p>这些属性可以来自 Item、Forge、Strengthen、Gem、Skills 或其他模块写入的 PDC。Attribute 负责汇总和计算，而不是让其他插件各自重复实现一套数值系统。</p><h2 id="默认配置目录" tabindex="-1">默认配置目录 <a class="header-anchor" href="#默认配置目录" aria-label="Permalink to &quot;默认配置目录&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/EmakiAttribute/</span></span>
<span class="line"><span>├── config.yml</span></span>
<span class="line"><span>├── attribute_balance.yml</span></span>
<span class="line"><span>├── attributes/</span></span>
<span class="line"><span>├── conditions/</span></span>
<span class="line"><span>├── damage_types/</span></span>
<span class="line"><span>├── lore_formats/</span></span>
<span class="line"><span>├── presets/</span></span>
<span class="line"><span>├── gui/</span></span>
<span class="line"><span>├── lang/</span></span>
<span class="line"><span>└── data/</span></span></code></pre></div><p>目录说明：</p><table tabindex="0"><thead><tr><th>目录 / 文件</th><th>作用</th></tr></thead><tbody><tr><td><code>attributes/</code></td><td>每个属性的定义。</td></tr><tr><td><code>damage_types/</code></td><td>伤害类型，例如 physical、projectile、spell。</td></tr><tr><td><code>conditions/</code></td><td>属性读取条件（PDC 读取规则）定义。</td></tr><tr><td><code>lore_formats/</code></td><td>属性在 Lore 中的展示格式。</td></tr><tr><td><code>attribute_balance.yml</code></td><td>属性平衡语义与战力权重配置。</td></tr><tr><td><code>presets/</code></td><td>属性预设定义。</td></tr><tr><td><code>gui/</code></td><td>属性点 GUI 配置（<code>attribute_points.yml</code>）。</td></tr><tr><td><code>lang/</code></td><td>语言文件（内置 <code>zh_CN.yml</code>、<code>en_US.yml</code>）。</td></tr><tr><td><code>data/</code></td><td>运行时数据，例如 <code>data/parent_attributes/&lt;UUID&gt;.yml</code>。</td></tr></tbody></table><h2 id="典型工作流" tabindex="-1">典型工作流 <a class="header-anchor" href="#典型工作流" aria-label="Permalink to &quot;典型工作流&quot;">​</a></h2><ol><li>在 <code>attributes/</code> 中定义属性。</li><li>在 <code>lore_formats/</code> 中定义展示格式。</li><li>在 <code>damage_types/</code> 中定义伤害类型如何计算。</li><li>让 Item / Forge / Strengthen / Gem 等模块写入属性 payload。</li><li>玩家装备变化或执行同步后，Attribute 汇总属性。</li><li>战斗发生时，根据伤害类型、攻击方属性、防御方属性计算结果。</li><li>通过消息、ActionBar、PAPI 或 debug 输出结果。</li></ol><h2 id="与其他模块的关系" tabindex="-1">与其他模块的关系 <a class="header-anchor" href="#与其他模块的关系" aria-label="Permalink to &quot;与其他模块的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>协作方式</th></tr></thead><tbody><tr><td>EmakiItem</td><td>自定义物品可以携带基础属性和套装属性。</td></tr><tr><td>EmakiForge</td><td>锻造结果可写入额外属性。</td></tr><tr><td>EmakiStrengthen</td><td>强化星级可增加属性。</td></tr><tr><td>EmakiGem</td><td>宝石可提供属性。</td></tr><tr><td>EmakiSkills</td><td>技能释放可读取或消耗 Attribute 资源，也可检查属性门槛。</td></tr><tr><td>MythicMobs</td><td>可作为技能或怪物战斗生态的一部分。</td></tr><tr><td>PlaceholderAPI</td><td>对外展示玩家属性、资源或战斗数据。</td></tr></tbody></table><h2 id="功能页面" tabindex="-1">功能页面 <a class="header-anchor" href="#功能页面" aria-label="Permalink to &quot;功能页面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>内容</th></tr></thead><tbody><tr><td><a href="./configuration.html">配置目录</a></td><td>主配置、属性目录、伤害目录、条件目录和排查顺序。</td></tr><tr><td><a href="./attributes.html">属性定义</a></td><td>属性字段、展示格式和属性 ID 设计。</td></tr><tr><td><a href="./scaling-curves.html">属性衰减曲线</a></td><td>高数值属性的阈值、曲线和调参建议。</td></tr><tr><td><a href="./damage.html">伤害系统</a></td><td>多阶段伤害管线、hard lock、命中反馈和恢复配置。</td></tr><tr><td><a href="./conditions.html">条件系统</a></td><td>装备条件、属性条件与跨模块条件。</td></tr><tr><td><a href="./lore-formats.html">Lore 格式</a></td><td>Lore 展示模板与读取正则。</td></tr><tr><td><a href="./commands.html">命令与权限</a></td><td><code>/ea</code> 命令、lint、preview、dump、source、trace 和调试。</td></tr><tr><td><a href="./placeholders.html">占位符</a></td><td>PlaceholderAPI 输出与伤害消息模板变量。</td></tr><tr><td><a href="./mythic.html">MythicMobs 集成</a></td><td>属性伤害 mechanic、临时属性 mechanic 与属性条件。</td></tr><tr><td><a href="./corelib-actions.html">CoreLib 动作</a></td><td>Attribute 注册的 Action ID 与参数。</td></tr><tr><td><a href="./api.html">API</a></td><td><code>EmakiAttributeApi</code>、<code>PdcAttributeApi</code> 与接入约定。</td></tr><tr><td><a href="./events.html">事件 API</a></td><td>对外公开的 Bukkit 事件。</td></tr><tr><td><a href="./damage-event.html">伤害事件 API</a></td><td><code>EmakiAttributeDamageEvent</code> 详解。</td></tr></tbody></table><h2 id="建议配置顺序" tabindex="-1">建议配置顺序 <a class="header-anchor" href="#建议配置顺序" aria-label="Permalink to &quot;建议配置顺序&quot;">​</a></h2><ol><li>先使用默认属性启动服务器，确认模块正常加载。</li><li>添加或修改一个属性文件，执行 reload / lint 检查。</li><li>让一个测试物品写入该属性。</li><li>使用 preview / dump 命令确认属性被读取。</li><li>再接入伤害类型和战斗测试。</li></ol><h2 id="config-yml-主要字段" tabindex="-1">config.yml 主要字段 <a class="header-anchor" href="#config-yml-主要字段" aria-label="Permalink to &quot;config.yml 主要字段&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>language</code></td><td>string</td><td><code>zh_CN</code></td><td>语言文件名（对应 <code>lang/</code> 目录下的文件）。</td></tr><tr><td><code>release_default_data</code></td><td>boolean</td><td><code>true</code></td><td>是否释放内置示例属性、伤害类型、条件与词条格式。</td></tr><tr><td><code>hard_lock_damage</code></td><td>boolean</td><td><code>true</code></td><td>全局硬锁定伤害。为 true 时所有匹配的伤害事件都走属性系统。</td></tr><tr><td><code>default_damage_type</code></td><td>string</td><td><code>physical</code></td><td>默认伤害类型 ID。未匹配到特定类型时使用。</td></tr><tr><td><code>projectile_damage_type</code></td><td>string</td><td><code>projectile</code></td><td>投射物命中时使用的伤害类型 ID。</td></tr><tr><td><code>vanilla_event_damage.enabled</code></td><td>boolean</td><td><code>true</code></td><td>原版事件伤害完美接管；关闭时走兼容合成伤害模式。</td></tr><tr><td><code>vanilla_event_damage.damage_type</code></td><td>string</td><td>同 <code>default_damage_type</code></td><td>未单独映射的原版伤害使用的伤害类型。</td></tr><tr><td><code>same_signature_ignores_invulnerability.enabled</code></td><td>boolean</td><td><code>true</code></td><td>同批次同签名攻击是否互相无视原版受伤间隔。</td></tr><tr><td><code>same_signature_ignores_invulnerability.window_ms</code></td><td>long</td><td><code>500</code></td><td>同批次判定时间窗，单位毫秒。</td></tr><tr><td><code>regen_interval_ticks</code></td><td>integer</td><td><code>20</code></td><td>资源回复计算间隔（tick）。最小值 1。20 tick = 1 秒。</td></tr><tr><td><code>sync_delay_ticks</code></td><td>integer</td><td><code>1</code></td><td>属性同步延迟（tick）。装备变化后等待多少 tick 再同步。最小值 0。</td></tr><tr><td><code>health_display_scaling.enabled</code></td><td>boolean</td><td><code>false</code></td><td>是否压缩客户端血条显示；不改变真实生命与伤害结算。</td></tr><tr><td><code>health_display_scaling.target</code></td><td>double</td><td><code>20.0</code></td><td>客户端显示的目标血量。</td></tr><tr><td><code>synthetic_hit_feedback.knockback</code></td><td>boolean</td><td><code>true</code></td><td>兼容模式下合成伤害是否补发击退。</td></tr><tr><td><code>synthetic_hit_feedback.knockback_strength</code></td><td>double</td><td><code>0.4</code></td><td>击退强度。</td></tr><tr><td><code>synthetic_hit_feedback.hurt_sound</code></td><td>boolean</td><td><code>true</code></td><td>兼容模式下合成伤害是否播放受伤音效。</td></tr></tbody></table><h3 id="资源配置" tabindex="-1">资源配置 <a class="header-anchor" href="#资源配置" aria-label="Permalink to &quot;资源配置&quot;">​</a></h3><p><code>default_profile.resources</code> 定义玩家默认资源：</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>同小节 key</td><td>资源 ID（如 <code>health</code>、<code>mana</code>）；内置配置用小节 key 表示。</td></tr><tr><td><code>display_name</code></td><td>string</td><td>同 <code>id</code></td><td>显示名称。</td></tr><tr><td><code>default_max</code></td><td>double</td><td><code>0</code></td><td>默认最大值。</td></tr><tr><td><code>min_max</code></td><td>double</td><td><code>0</code></td><td>最大值下限（属性加成后不低于此值）。</td></tr><tr><td><code>max_max</code></td><td>double</td><td>极大值</td><td>最大值上限。</td></tr><tr><td><code>sync_to_bukkit</code></td><td>boolean</td><td><code>false</code></td><td>是否同步到 Bukkit 原版生命值（仅 health 资源需要）。</td></tr><tr><td><code>full_on_init</code></td><td>boolean</td><td><code>true</code></td><td>初始化时是否填满资源。</td></tr><tr><td><code>regen_per_second</code></td><td>double</td><td><code>0</code></td><td>每秒自然回复量。</td></tr></tbody></table><p>内置默认资源：</p><ul><li><code>health</code>：默认最大 20，同步到 Bukkit，最小上限 1，最大上限 2048。</li><li><code>mana</code>：默认最大 100，不同步到 Bukkit，最小上限 0，最大上限 99999。</li></ul><h2 id="attribute-注册的动作" tabindex="-1">Attribute 注册的动作 <a class="header-anchor" href="#attribute-注册的动作" aria-label="Permalink to &quot;Attribute 注册的动作&quot;">​</a></h2><p>EmakiAttribute 会向 CoreLib 动作系统注册属性伤害、临时属性、资源、标签和同步动作。完整 Action ID、参数和示例已拆分到 <a href="./corelib-actions.html">CoreLib 动作</a>。</p><p>常用示例：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;attributedamage amount=50 type=physical&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;attribute_add effect_id=forge_buff attribute=physical_attack value=20 duration_ticks=10s&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;attribute_resource_consume resource=mana amount=20&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;attribute_sync all=false&#39;</span></span></code></pre></div>`,31)])])}const u=d(r,[["render",o]]);export{b as __pageData,u as default};
